import Head from '@docusaurus/Head'
import React from 'react'

/**
 * Points to the Markdown version of the page generated by the llms plugin
 * (see src/plugins/llms), so LLM tools can discover it.
 */
export const toMdPath = (permalink) =>
    permalink.endsWith('/') ? `${permalink}index.md` : `${permalink}.md`

export const MarkdownAlternateLink = ({ permalink }) => (
    <Head>
        <link rel="alternate" type="text/markdown" href={toMdPath(permalink)} />
    </Head>
)
